FROM python:3.7-alpine3.8

ENV workdir /data
WORKDIR ${workdir}

RUN mkdir -p ${workdir} && adduser python --disabled-password
COPY . ${workdir}
WORKDIR ${workdir}
RUN pip install --upgrade google-api-python-client oauth2client progressbar2 && \
    python setup.py install

USER python

ENTRYPOINT ["youtube-upload"]

from .. import lib

try:
    from youtube_upload.auth import webkit_qt as backend
    WEBKIT_BACKEND = "qt"
except ImportError:
    try:
        from youtube_upload.auth import webkit_gtk as backend
        WEBKIT_BACKEND = "gtk"
    except ImportError:
        WEBKIT_BACKEND = None

def get_code(url, size=(640, 480), title="Google authentication"):
    if WEBKIT_BACKEND:
        lib.debug("Using webkit backend: " + WEBKIT_BACKEND)
        with lib.default_sigint():
            return backend.get_code(url, size=size, title=title)
    else:
        raise NotImplementedError("GUI auth requires pywebkitgtk or qtwebkit")

import json

CHECK_AUTH_JS = """
    var code = document.getElementById("code");
    var access_denied = document.getElementById("access_denied");
    var result;

    if (code) {
        result = {authorized: true, code: code.value};
    } else if (access_denied) {
        result = {authorized: false, message: access_denied.innerText};
    } else {
        result = {};
    }
    window.status = JSON.stringify(result);
"""

def _on_webview_status_bar_changed(webview, status, dialog):
    if status:
        authorization = json.loads(status)
        if authorization.has_key("authorized"):
            dialog.set_data("authorization_code", authorization["code"])
            dialog.response(0)

def get_code(url, size=(640, 480), title="Google authentication"):
    """Open a GTK webkit window and return the access code."""
    import gtk
    import webkit
    dialog = gtk.Dialog(title=title)
    webview = webkit.WebView()
    scrolled = gtk.ScrolledWindow()
    scrolled.add(webview)
    dialog.get_children()[0].add(scrolled)
    webview.load_uri(url)    
    dialog.resize(*size)
    dialog.show_all()
    dialog.connect("delete-event", 
        lambda event, data: dialog.response(1))
    webview.connect("load-finished", 
        lambda view, frame: view.execute_script(CHECK_AUTH_JS))       
    webview.connect("status-bar-text-changed", 
        _on_webview_status_bar_changed, dialog)
    dialog.set_data("authorization_code", None)
    status = dialog.run()
    dialog.destroy()
    while gtk.events_pending():
        gtk.main_iteration(False)
    return dialog.get_data("authorization_code")

CHECK_AUTH_JS = """
    var code = document.getElementById("code");
    var access_denied = document.getElementById("access_denied");
    var result;

    if (code) {
        result = {authorized: true, code: code.value};
    } else if (access_denied) {
        result = {authorized: false, message: access_denied.innerText};
    } else {
        result = {};
    }
    result;
"""

def _on_qt_page_load_finished(dialog, webview):
    frame = webview.page().currentFrame()
    try: #PySide does not QStrings
        from QtCore import QString
        jscode = QString(CHECK_AUTH_JS)
    except ImportError:
        jscode = CHECK_AUTH_JS
    res = frame.evaluateJavaScript(jscode)
    try:
        authorization = dict((_to_string(k), _to_string(v)) for (k, v) in res.toPyObject().items())
    except AttributeError: #PySide returns the result in pure Python
        authorization = dict((_to_string(k), _to_string(v)) for (k, v) in res.items())
    if "authorized" in authorization:
        dialog.authorization_code = authorization.get("code")
        dialog.close()

def _to_string(x):
    return str(x.toUtf8()) if hasattr(x,'toUtf8') else x

def get_code(url, size=(640, 480), title="Google authentication"):
    """Open a QT webkit window and return the access code."""
    try:
        from PyQt4 import QtCore, QtGui, QtWebKit
    except ImportError:
        try:
            from PySide6 import QtCore, QtWebEngineWidgets
            from PySide6.QtCore import QUrl
            from PySide6.QtWidgets import QApplication, QDialog, QGridLayout
            from PySide6.QtWebEngineCore import QWebEnginePage

            # Use WebEngine for PySide6
            app = QApplication.instance()
            if app is None:
                app = QApplication([])
            dialog = QDialog()
            dialog.setWindowTitle(title)
            dialog.resize(*size)
            webview = QtWebEngineWidgets.QWebEngineView()
            webpage = QWebEnginePage()
            webview.setPage(webpage)

            # For PySide6, we need to handle the load finished signal differently
            def on_load_finished(success):
                if success:
                    # Run JavaScript to get authorization code
                    webview.page().runJavaScript(CHECK_AUTH_JS, lambda result: handle_js_result(result, dialog))

            def handle_js_result(result, dialog):
                if result and isinstance(result, dict) and "authorized" in result:
                    dialog.authorization_code = result.get("code")
                    dialog.close()

            webpage.loadFinished.connect(on_load_finished)
            webview.setUrl(QUrl(url))
            layout = QGridLayout()
            layout.addWidget(webview)
            dialog.setLayout(layout)
            dialog.authorization_code = None
            dialog.show()
            app.exec_()
            return dialog.authorization_code
        except ImportError:
            from PySide import QtCore, QtGui, QtWebKit
    app = QtGui.QApplication([])
    dialog = QtGui.QDialog()
    dialog.setWindowTitle(title)
    dialog.resize(*size)
    webview = QtWebKit.QWebView()
    webpage = QtWebKit.QWebPage()
    webview.setPage(webpage)           
    webpage.loadFinished.connect(lambda: _on_qt_page_load_finished(dialog, webview))
    webview.setUrl(QtCore.QUrl.fromEncoded(url))
    layout = QtGui.QGridLayout()
    layout.addWidget(webview)
    dialog.setLayout(layout)
    dialog.authorization_code = None
    dialog.show()
    app.exec_()
    return dialog.authorization_code

"""Lightweight, best-effort content validation for video files."""
from __future__ import annotations

from pathlib import Path
from typing import Callable

from . import main


def _read_head(path: Path, size: int = 4096) -> bytes:
    with path.open("rb") as handle:
        return handle.read(size)


def _starts_with(data: bytes, prefix: bytes) -> bool:
    return data.startswith(prefix)


def _contains_at(data: bytes, needle: bytes, offset: int) -> bool:
    return len(data) >= offset + len(needle) and data[offset:offset + len(needle)] == needle


def _check_mp4_like(data: bytes) -> bool:
    # MP4/QuickTime/3GP should contain an ftyp box near the beginning.
    return _contains_at(data, b"ftyp", 4) or (b"ftyp" in data)


def _check_webm(data: bytes) -> bool:
    return _starts_with(data, b"\x1a\x45\xdf\xa3")


def _check_flv(data: bytes) -> bool:
    return _starts_with(data, b"FLV")


def _check_mpeg_ps(data: bytes) -> bool:
    return _starts_with(data, b"\x00\x00\x01\xba")


def _check_avi(data: bytes) -> bool:
    return _starts_with(data, b"RIFF") and _contains_at(data, b"AVI ", 8)


def _check_asf_wmv(data: bytes) -> bool:
    return _starts_with(data, b"\x30\x26\xb2\x75\x8e\x66\xcf\x11")


_SIGNATURE_CHECKS: dict[str, Callable[[bytes], bool]] = {
    # MP4/QuickTime family
    "mp4": _check_mp4_like,
    "mpeg4": _check_mp4_like,
    "mov": _check_mp4_like,
    "3gp": _check_mp4_like,
    "3gpp": _check_mp4_like,
    # WebM
    "webm": _check_webm,
    # FLV
    "flv": _check_flv,
    # MPEG Program Stream
    "mpeg": _check_mpeg_ps,
    "mpeg1": _check_mpeg_ps,
    "mpeg2": _check_mpeg_ps,
    "mpg": _check_mpeg_ps,
    "mpegps": _check_mpeg_ps,
    # AVI
    "avi": _check_avi,
    # ASF/WMV
    "wmv": _check_asf_wmv,
}

def _matches_any_known_signature(data: bytes) -> bool:
    return any(check(data) for check in _SIGNATURE_CHECKS.values())


def validate_video_content(video_path: str, minimum_size_bytes: int = 1024) -> None:
    """
    Ensure the file has video-like content and matches its container signature.
    Raises main.InvalidVideoFormat on failure.
    """
    path = Path(video_path)
    if not path.exists():
        raise main.InvalidVideoFormat(f"File does not exist: {video_path}")
    if path.stat().st_size < minimum_size_bytes:
        raise main.InvalidVideoFormat(f"File too small to be a valid video: {video_path}")

    suffix = path.suffix.lower().lstrip(".")
    data = _read_head(path)
    checker = _SIGNATURE_CHECKS.get(suffix)
    if checker:
        if checker(data):
            return
        # Allow other known video signatures even if the extension doesn't match.
        if _matches_any_known_signature(data):
            return
        raise main.InvalidVideoFormat(
            f"Content of '{video_path}' does not look like a valid {suffix.upper()} video."
        )
    else:
        if _matches_any_known_signature(data):
            return
        # For less common extensions (hevc, h265, prores, cineform, dnxhr) perform a generic sanity check.
        if data.startswith(b"\x00\x00\x00\x00") or all(b == 0x00 for b in data[:16]):
            raise main.InvalidVideoFormat(
                f"Content of '{video_path}' does not appear to contain valid video data."
            )


__all__ = ["validate_video_content"]

from __future__ import print_function
import os
import sys
import locale
import random
import time
import signal
from contextlib import contextmanager
import threading

import googleapiclient.errors

@contextmanager
def default_sigint():
    """
    Temporarily restore the default SIGINT handler.

    Tk/GUI flows run CLI work on a background thread; calling signal.signal
    outside the main thread raises "signal only works in main thread".
    If we're not on the main thread, skip changing handlers to keep the
    worker thread happy while preserving main-thread behavior elsewhere.
    """
    if threading.current_thread() is not threading.main_thread():
        # No-op when called off the main thread to avoid RuntimeError.
        yield
        return

    original_sigint_handler = signal.getsignal(signal.SIGINT)
    signal.signal(signal.SIGINT, signal.SIG_DFL)
    try:
        yield
    finally:
        signal.signal(signal.SIGINT, original_sigint_handler)

def get_encoding():
    return locale.getpreferredencoding()

def to_utf8(s):
    """Re-encode string from the default system encoding to UTF-8."""
    current = locale.getpreferredencoding()
    if hasattr(s, 'decode'): #Python 3 workaround
        return (s.decode(current).encode("UTF-8") if s and current != "UTF-8" else s)
    elif isinstance(s, bytes):
        return bytes.decode(s)
    else:
        return s

def debug(obj, fd=sys.stderr):
    """Write obj to standard error."""
    print(obj, file=fd)

def catch_exceptions(exit_codes, fun, *args, **kwargs):
    """
    Catch exceptions on fun(*args, **kwargs) and return the exit code specified
    in the exit_codes dictionary. Return 0 if no exception is raised.
    """
    try:
        fun(*args, **kwargs)
        return 0
    except tuple(exit_codes.keys()) as exc:
        debug("[{0}] {1}".format(exc.__class__.__name__, exc))
        return exit_codes[exc.__class__]

def first(it):
    """Return first element in iterable."""
    return it.next()

def string_to_dict(string):
    """Return dictionary from string "key1=value1, key2=value2"."""
    if string:
        pairs = [s.strip() for s in string.split(",")]
        return dict(pair.split("=") for pair in pairs)

def get_first_existing_filename(prefixes, relative_path):
    """Get the first existing filename of relative_path seeking on prefixes directories."""
    for prefix in prefixes:
        path = os.path.join(prefix, relative_path)
        if os.path.exists(path):
            return path

def retriable_exceptions(fun, retriable_exceptions, max_retries=None):
    """Run function and retry on some exceptions (with exponential backoff)."""
    retry = 0
    while 1:
        try:
            return fun()
        except tuple(retriable_exceptions) as exc:
            retry += 1
            if type(exc) not in retriable_exceptions:
                raise exc
            # we want to retry 5xx errors only
            elif type(exc) == googleapiclient.errors.HttpError and exc.resp.status < 500:
                raise exc
            elif max_retries is not None and retry > max_retries:
                debug("[Retryable errors] Retry limit reached")
                raise exc
            else:
                seconds = random.uniform(0, 2**retry)
                message = ("[Retryable error {current_retry}/{total_retries}] " +
                    "{error_type} ({error_msg}). Wait {wait_time} seconds").format(
                    current_retry=retry, 
                    total_retries=max_retries or "-", 
                    error_type=type(exc).__name__, 
                    error_msg=str(exc) or "-", 
                    wait_time="%.1f" % seconds,
                )
                debug(message)
                time.sleep(seconds)

import locale
import sys

from .lib import debug

def get_playlist(youtube, title):
    """Return users's playlist ID by title (None if not found)"""
    playlists = youtube.playlists()
    request = playlists.list(mine=True, part="id,snippet")
    current_encoding = locale.getpreferredencoding()

    while request:
        results = request.execute()
        for item in results["items"]:
            t = item.get("snippet", {}).get("title")
            existing_playlist_title = (t.encode(current_encoding) if hasattr(t, 'decode') else t)
            if existing_playlist_title == title:
                return item.get("id")
        request = playlists.list_next(request, results)

def create_playlist(youtube, title, privacy):
    """Create a playlist by title and return its ID"""
    debug("Creating playlist: {0}".format(title))
    response = youtube.playlists().insert(part="snippet,status", body={
        "snippet": {
            "title": title,
        },
        "status": {
            "privacyStatus": privacy,
        }
    }).execute()
    return response.get("id")

def video_in_playlist(youtube, playlist_id, video_id):
    """Return True if the video is already in the playlist."""
    playlist_items = youtube.playlistItems()
    request = playlist_items.list(
        part="id",
        playlistId=playlist_id,
        videoId=video_id,
        maxResults=1,
    )
    while request:
        results = request.execute()
        if results.get("items"):
            return True
        request = playlist_items.list_next(request, results)
    return False

def add_video_to_existing_playlist(youtube, playlist_id, video_id):
    """Add video to playlist (by identifier) and return the playlist ID."""
    if video_in_playlist(youtube, playlist_id, video_id):
        debug("Video already in playlist: {0}".format(video_id))
        return None
    debug("Adding video to playlist: {0}".format(playlist_id))
    return youtube.playlistItems().insert(part="snippet", body={
        "snippet": {
            "playlistId": playlist_id,
            "resourceId": {
                "kind": "youtube#video",
                "videoId": video_id,
            }
        }
    }).execute()

def add_video_to_playlist(youtube, video_id, title, privacy="public"):
    """Add video to playlist (by title) and return the full response."""
    playlist_id = get_playlist(youtube, title)
    if not playlist_id:
        # Ask user for confirmation when running interactively; otherwise create silently.
        create = True
        if sys.stdin is not None and sys.stdin.isatty():
            try:
                answer = input(f'Playlist "{title}" not found. Create it? [y/N]: ').strip().lower()
                create = answer in ("y", "yes")
            except (EOFError, KeyboardInterrupt):
                create = False
        if create:
            playlist_id = create_playlist(youtube, title, privacy)
        else:
            debug(f'Skipping playlist creation for "{title}".')
            return None
    if playlist_id:
        return add_video_to_existing_playlist(youtube, playlist_id, video_id)
    else:
        debug("Error adding video to playlist")

